package com.travelbird.ai.service;
import static org.mockito.Mockito.*;import com.travelbird.ai.client.*;import com.travelbird.ai.dto.internal.*;import com.travelbird.ai.entity.AiRequestType;import com.travelbird.global.error.ErrorCode;import com.travelbird.trip.entity.*;import java.time.*;import java.util.List;import org.junit.jupiter.api.Test;
class AiRecommendationDispatcherTest{
 @Test void syncCompletesBeforeRecommendationAndProcessing(){var client=mock(AiRecommendationClient.class);var transitions=mock(AiJobTransitionService.class);when(transitions.prepare(7L,"fp")).thenReturn(true);when(client.recommend(any())).thenReturn(new AiServerAcceptedResponse(7L,"PENDING",OffsetDateTime.now()));var dispatcher=new AiRecommendationDispatcher(client,transitions);var event=event(false);dispatcher.dispatchOnce(event);var order=inOrder(client,transitions);order.verify(transitions).prepare(7L,"fp");order.verify(client).sync(event.syncRequest());order.verify(client).recommend(event.request());order.verify(transitions).processing(7L);}
 @Test void syncFailureMarksJobFailedAndNeverRecommends(){var client=mock(AiRecommendationClient.class);var transitions=mock(AiJobTransitionService.class);when(transitions.prepare(7L,"fp")).thenReturn(true);doThrow(new AiClientException(ErrorCode.AI_SERVICE_UNAVAILABLE,"down",null)).when(client).sync(any());var dispatcher=new AiRecommendationDispatcher(client,transitions);dispatcher.dispatchOnce(event(false));verify(client,never()).recommend(any());verify(transitions).failed(eq(7L),eq(com.travelbird.global.error.AiJobFailureCode.AI_PLACE_SYNC_FAILED),anyString(),eq(true));}
 private AiDispatchRequested event(boolean empty){var request=new RecommendationJobRequest(7L,AiRequestType.GENERAL,"11110",LocalDate.of(2026,10,1),LocalDate.of(2026,10,2),CompanionType.SOLO,List.of(TravelTheme.FOOD),Pace.NORMAL,List.of(),List.of(),List.of(),true);var item=new PlaceSyncRequest.PlaceSyncItem(1L,"11110","n","a",java.math.BigDecimal.ONE,java.math.BigDecimal.ONE,com.travelbird.place.entity.PlaceCategory.FOOD);return new AiDispatchRequested(request,new PlaceSyncRequest(empty?List.of():List.of(item)),"fp");}
}
